// Probe the server: is anyone home, and which model is loaded?
const BASE = 'http://127.0.0.1:1234';

let models;
try {
  const res = await fetch(BASE + '/v1/models');
  if (!res.ok) throw new Error('HTTP ' + res.status);
  models = (await res.json()).data || [];
} catch (err) {
  console.warn('no LM Studio at ' + BASE + ' (' + err.message + ')');
  console.warn('start it: LM Studio -> Developer -> Start Server, load a model, re-run me');
  nb.set('llm_server', { base: BASE, up: false, models: [] });
  return 'server not reachable - the chat below will also tell you this';
}

console.log('server is up with ' + models.length + ' model(s):');
models.slice(0, 8).forEach(m => console.log('  ' + m.id));

// one non-streamed round trip, so the plain-request shape is on record
const t0 = performance.now();
const chat = await fetch(BASE + '/v1/chat/completions', {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({
    messages: [{ role: 'user', content: 'Reply with exactly five words about notebooks.' }],
    temperature: 0.2,
    max_tokens: 30,
  }),
});
const answer = await chat.json();
const ms = Math.round(performance.now() - t0);
console.log('\nround trip in ' + ms + 'ms: "' + answer.choices[0].message.content.trim() + '"');
if (answer.usage) {
  console.log('tokens: ' + answer.usage.prompt_tokens + ' in, ' +
    answer.usage.completion_tokens + ' out');
}

nb.set('llm_server', { base: BASE, up: true, models: models.map(m => m.id) });
return { up: true, models: models.length, firstReplyMs: ms };
